import{_ as i,o as a,c as d,a2 as s}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"Hearth Windows 桌面版 v0.3.4（Tauri）","description":"","frontmatter":{},"headers":[],"relativePath":"design/desktop.md","filePath":"design/desktop.md","lastUpdated":1795426969000}'),t={name:"design/desktop.md"};function o(l,e,r,c,h,n){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="hearth-windows-桌面版-v0-3-4-tauri" tabindex="-1">Hearth Windows 桌面版 v0.3.4（Tauri） <a class="header-anchor" href="#hearth-windows-桌面版-v0-3-4-tauri" aria-label="Permalink to &quot;Hearth Windows 桌面版 v0.3.4（Tauri）&quot;">​</a></h1><p>桌面版只有一套实现：Tauri 2 外壳 + 官方 Node 运行时 + 原来的 Fastify / React / SQLite 应用。目标是把仓库里的完整应用打成可双击运行的程序，同时继续使用现有数据，不牺牲任何已有功能。</p><p>完整的压缩过程、每一步的体积变化、复现命令和对外分发时的使用前提见 <a href="./desktop-compression.html">桌面版压缩实录</a>。</p><h2 id="运行形态" tabindex="-1">运行形态 <a class="header-anchor" href="#运行形态" aria-label="Permalink to &quot;运行形态&quot;">​</a></h2><ul><li>Tauri 主程序负责窗口、托盘、数据目录选择、环境体检和服务端生命周期，安装后约 7.8 MiB。</li><li>服务端是原来的 Fastify 应用，由 esbuild 打成 <code>server.mjs</code> 入口（约 2.1 MiB）和按需加载的 <code>chunk-*.mjs</code>，作为 Tauri 的子进程运行，固定监听 <code>127.0.0.1:4317</code>。邮件 SDK、文档解析、PDF、浏览器自动化等重依赖只在首次用到时加载。</li><li>内置官方 Node <code>22.23.2</code>（<code>node.exe</code>，83.0 MiB）和随附 npm <code>10.9.8</code>（裁剪后约 7.8 MiB）。托管安装、运行时 <code>npm</code> 命令都使用内置 npm。</li><li>前端构建产物在 <code>resources/web</code>（约 0.8 MiB，默认不生成 source map）。PDF worker 与 cMaps / 标准字体 / wasm 在 <code>resources/server</code>（合计约 4.5 MiB）。</li><li>原生沙箱 helper 是 <code>resources/native/hearth-native.exe</code>（约 21 KiB，由 <code>scripts/build-native.mjs</code> 调用系统 <code>csc.exe</code> 编译），负责 AppContainer、ACL、Job Object 与 ConPTY；<code>resources/sandbox</code> 里的旧 <code>@deepseek-ai/dsh-sandbox-windows-acl</code>（约 12.8 MiB）仍随包携带，但当前 native 沙箱不再使用，属于待清理体积。</li><li>Codex 不内置约 479 MiB 的平台二进制：优先 <code>HEARTH_CODEX_PATH</code>，其次 <code>where codex.exe</code> 的第一个 <code>.exe</code>，最后已知 npm 全局路径。</li><li>桌面版和开发服务器不能同时使用同一个 <code>.hearth</code>；数据目录锁会拒绝第二个实例。</li></ul><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm ci</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm run tauri:build</span></span></code></pre></div><p>流程：web build → server 分包 bundle → 编译 <code>resources/native/hearth-native.exe</code> → 复制 web → 下载并校验官方 Node 22.23.2 → 复制/裁剪 npm → 生成 <code>npm.cmd</code> 与 helper 启动脚本 → <code>tauri build</code>。</p><p>产物：</p><ul><li><code>release/Hearth_0.3.4_x64-setup.exe</code>：NSIS 按用户安装，免 UAC，带开始菜单快捷方式。</li><li>0.3.4 安装包与便携 zip 同步发布到 <a href="https://github.com/hearthproject/hearth-os/releases" target="_blank" rel="noreferrer">GitHub Releases</a>（Pre-release），附 SHA256 校验和。</li><li>安装目录：<code>%LOCALAPPDATA%\\Programs\\Hearth</code>，刻意与数据目录 <code>%LOCALAPPDATA%\\Hearth</code> 分开。</li><li>WebView2 使用在线 bootstrapper；Windows 10/11 通常已自带运行时，不额外占安装体积。</li></ul><p>构建缓存位于 <code>apps/desktop-tauri/.cache</code>（Node zip 与解压目录），可随时删除。若官方 Node 下载失败，可把 <code>HEARTH_NODE_PATH</code> 指向官方 Node v22.x 的 <code>node.exe</code>。</p><h2 id="体积去向" tabindex="-1">体积去向 <a class="header-anchor" href="#体积去向" aria-label="Permalink to &quot;体积去向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组成</th><th style="text-align:right;">安装后</th></tr></thead><tbody><tr><td><code>node.exe</code>（官方 22.23.2）</td><td style="text-align:right;">83.0 MiB</td></tr><tr><td>server（单文件 + PDF worker + PDF 资源）</td><td style="text-align:right;">18.6 MiB</td></tr><tr><td><code>resources/sandbox</code>（旧 dsh ACL runner，当前未使用）</td><td style="text-align:right;">12.8 MiB</td></tr><tr><td>内置 npm</td><td style="text-align:right;">7.8 MiB</td></tr><tr><td>web 静态资源</td><td style="text-align:right;">0.8 MiB</td></tr><tr><td>Tauri 主程序</td><td style="text-align:right;">7.8 MiB</td></tr><tr><td><code>hearth-native.exe</code> / helper / 许可证 / 第三方声明</td><td style="text-align:right;">0.3 MiB</td></tr><tr><td><strong>合计</strong></td><td style="text-align:right;"><strong>约 131 MiB</strong></td></tr><tr><td>NSIS 安装包</td><td style="text-align:right;">30.5 MiB</td></tr></tbody></table><p>不计入安装体积：<code>.hearth</code> 业务数据（当前约 1.03 GB）、系统共享的 WebView2 运行时、每应用 WebView2 缓存 <code>%LOCALAPPDATA%\\ai.hearth.os</code>（约 80 MiB，可安全清理）。</p><p>进一步压缩的边界：不修改官方 Node（不做 small-icu、UPX、按需下载），不删除 npm，不删除 PDF cMaps / 标准字体 / wasm，也不把浏览器自动化或 Windows ACL sandbox 改成运行时下载。</p><h2 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h2><p>首次启动会弹出原生 Windows 对话框三选一：</p><ul><li>使用现有数据：设置 <code>HEARTH_EXISTING_ROOT</code> 指向数据根目录（其下应有 <code>.hearth\\hearth.sqlite</code>）；未设置时会打开原生文件夹选择框，浏览选择已有数据根目录。</li><li>新建数据目录：<code>%LOCALAPPDATA%\\Hearth</code>。</li><li>退出。</li></ul><p>选择会写入 <code>%LOCALAPPDATA%\\Hearth\\desktop.json</code>，结构为 <code>{version:1, root, dataDir, lastLaunchAt}</code>；旧的只含 <code>{root}</code> 的文件仍可读取。<code>HEARTH_ROOT</code> 只作为测试/覆盖入口，不覆盖 <code>desktop.json</code>。</p><p>数据根下必须有 <code>.hearth</code>，桌面版不会静默复制旧数据库。数据库大于 600 MB 时，复制既慢又容易漏掉 <code>master.key</code>、模型设置和 worktree 绝对路径，因此 v0.1 就地使用。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><ul><li>单实例：第二次启动会聚焦已有窗口。</li><li>启动前探测 4317：已有 Hearth 会提示先退出旧实例；被其他程序占用会提示并退出。</li><li>关窗不退出，窗口隐藏到托盘。</li><li>托盘菜单：打开 Hearth、环境体检、桌面助手、数据目录、日志目录、退出；左键双击打开主窗口。</li><li>关闭窗口后服务端继续运行；托盘退出会先 POST <code>/api/desktop/shutdown</code>，再 <code>taskkill /T /F</code>，并清理与 PID 匹配的 <code>hearth.lock</code>。</li><li>服务端异常退出后按 1s、2s、5s、10s、30s 退避重启；成功就绪后重置计数，连续 5 次失败弹窗并停止。</li><li>日志：<code>%LOCALAPPDATA%\\Hearth\\logs\\main.log</code> 和 <code>server.log</code>，5 MiB 轮转保留 3 份；服务端 stdout/stderr 写入 <code>server.log</code>。</li></ul><h2 id="环境体检" tabindex="-1">环境体检 <a class="header-anchor" href="#环境体检" aria-label="Permalink to &quot;环境体检&quot;">​</a></h2><p>启动后后台执行一次，托盘“环境体检”可再次查看。检查项与旧 Electron 版一致：</p><ol><li>聊天模型：读取 <code>/api/health</code> 的 <code>chatModel.configured</code>。</li><li>Git：<code>git.exe --version</code>。</li><li>GitHub CLI：<code>gh.exe --version</code>。</li><li>Codex：<code>HEARTH_CODEX_PATH</code> → <code>where codex.exe</code> → 已知 npm 全局路径；优先取 <code>.exe</code>。</li><li>npm：内置 <code>node.exe + npm-cli.js --version</code>。</li><li>桌面助手：<code>resources/helper/helper.cmd</code> 是否存在。</li><li>端口：<code>/api/health</code> 是否能访问 <code>127.0.0.1:4317</code>。</li></ol><p>模型未配置时首次启动会弹一次引导，但不阻塞进入主界面；<code>HEARTH_ENV_SKIP_INTRO=1</code> 可跳过。检查结果不合格不会让应用白屏。</p><h2 id="桌面助手" tabindex="-1">桌面助手 <a class="header-anchor" href="#桌面助手" aria-label="Permalink to &quot;桌面助手&quot;">​</a></h2><p>托盘“桌面助手”用 <code>cmd /c resources/helper/helper.cmd</code> 启动带独立控制台的 helper。脚本直接调用内置 <code>node.exe</code>，不再依赖 Electron 的 <code>ELECTRON_RUN_AS_NODE</code> 或 <code>Hearth.exe</code>。helper 资源从 <code>tools/windows-helper</code> 复制，包含 <code>helper.mjs</code> 与 <code>windows.ps1</code>。</p><h2 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h2><ul><li>外部链接和新窗口只允许 http/https，交给系统浏览器；主窗口只允许 splash 与 <code>127.0.0.1:4317</code> 导航。</li><li>服务端在 <code>HEARTH_DESKTOP=1</code> 时通过 <code>onSend</code> 注入 CSP：<code>default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; ... frame-ancestors &#39;none&#39;</code>。</li><li>桌面模式注销 Service Worker，避免旧界面被缓存。</li><li>不绕过服务端已有的 loopback 与 Origin 校验。</li><li>不使用 rfd/dialog 插件，原生对话框直接调用 <code>MessageBoxW</code> / <code>ShellExecuteW</code>，减少体积。</li></ul><h2 id="烟测" tabindex="-1">烟测 <a class="header-anchor" href="#烟测" aria-label="Permalink to &quot;烟测&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用内置 Node 启动 staged server（单独端口，避免与桌面实例冲突）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;4399&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HEARTH_DESKTOP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apps\\desktop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri\\src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri\\resources\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">node.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apps\\desktop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri\\src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tauri\\resources\\server\\server.mjs</span></span></code></pre></div><p>验证 <code>/api/ready</code>、<code>/api/health</code>、<code>/api/executors</code>、<code>/</code>、CSP 响应头，以及任务附件中的中文 PDF。完整桌面验收覆盖窗口、托盘全部菜单、桌面助手控制台、环境体检、数据/日志目录、双击托盘、关窗进托盘、单实例聚焦、托盘退出清理 4317 与锁、结束 node 子进程后自动拉起。</p><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h2><ul><li>仅 Windows x64；不做代码签名、自动更新、便携版、macOS、Linux、多用户。</li><li>安装包没有签名，公开下载会触发 SmartScreen；当前只自己用。</li><li>Codex 使用系统或 <code>HEARTH_CODEX_PATH</code> 指向的 <code>codex.exe</code>；DeepSeek SDK 已直接打入 server 单文件，缺失外部运行时不影响 native / Codex。</li><li><code>resources/sandbox</code> 里的旧 dsh ACL runner 仍被 <code>scripts/build-server.mjs</code> 复制进安装包，但当前 native 沙箱只调用 <code>hearth-native.exe</code>；这是待清理的 12.8 MiB 体积。</li><li>Gmail OAuth 回调仍固定 <code>127.0.0.1:4317</code>，不要改成动态端口。</li><li>卸载不会删除 <code>%LOCALAPPDATA%\\Hearth</code> 数据目录，这是刻意的。</li></ul>`,35)])])}const u=i(t,[["render",o]]);export{k as __pageData,u as default};
